const getNames = (list) => list.map((p) => p.name)
const affordable = (list, max) => list.filter((p) => p.price <= max)
const findByName = (list, name) => list.find((p) => p.name === name)
const withVat = (list) => list.map((p) => ({ ...p, priceWithVat: p.price * 1.075 }))
const allInStock = (list) => list.every((p) => p.inStock)
